import sqlite3

app = Flask(__name__)

DATABASE = 'path/to/your/database.db'

@app.route('/user')
def get_user():
    username = request.args.get('username', default=None)
    if not username:
        return jsonify({"error": "Username required"}), 400

    conn = sqlite3.connect(DATABASE)
    cursor = conn.cursor()
    cursor.execute("SELECT * FROM users WHERE username=?", (username,)) 
    row = cursor.fetchone()

    if row is None:
        return jsonify({"error": "User not found"}), 404
    else:
        user = {
            "id": row[0],
            "username": row[1]
            # Add more fields as needed
        }
        return jsonify(user)

if __name__ == '__main__':
    app.run(debug=True)
```

This approach is simple and effective for direct lookup without any performance optimizations since it's assumed speed isn't a major concern.

