from flask import Flask, request, jsonify
import sqlite3

app = Flask(__name__)

def fetch_user(username):
    conn = sqlite3.connect("users.db")
    cursor = conn.cursor()
    cursor.execute("SELECT * FROM users WHERE username = ?", (username,))
    return cursor.fetchone()

@app.route("/users", methods=["GET"])
def get_user():
    if "query" in request.args:
        username = request.args.get("query")
        user_record = fetch_user(username)
        return jsonify(user_record)
    else:
        return "Missing username parameter."
```

This function will connect directly to a SQLite database named `users.db`. No need for extra packages or complex configuration.

